package agents

import (
	"crypto/rand"
	"fmt"
	"strings"
)

// The username: the handle a registration chooses for itself, and how one is
// generated when the caller does not.
//
// WHY THE SERVER GENERATES IT. The reference CLI generated the attempt
// client-side and retried on a 409/422 (`autogeneratedUsername`), which worked
// only because a client that lost the retry loop understood the conflict. Taking
// the retry in here means the CONFLICT never reaches the caller as information:
// registration either succeeds with a handle it now owns, or — on a handle the
// caller chose that is already gone — asks the caller to pick another. A
// generated collision mints a new suffix and tries again, inside one request.
//
// WHY THE SHAPE IS NARROW. A handle reaches a log line, an audit row, a
// management list and a future claim-screen URL. Lower-case alphanumerics joined
// by single dashes is the largest set that needs no escaping in any of those and
// that modem-era tooling types without quoting it. The database CHECK restates
// this shape (migration 00034); the two refuse the same set because this function
// is where the normalisation runs and the CHECK is copied from what it produces.
const (
	// usernameMin and usernameMax bound a handle, matching the CHECK. The floor
	// is 3 because a one- or two-character handle is nearly free to brute force as
	// a login; the ceiling leaves room for a 24-character slug plus a separator
	// and a suffix the way the reference composed them.
	usernameMin = 3
	usernameMax = 39
	// usernameBaseMax is how much of the display name survives into the slug
	// before the suffix is appended, so slug plus dash plus suffix cannot push a
	// generated handle over usernameMax.
	usernameBaseMax = 24
	// usernameSuffixLen is the random tail. Six base-36 characters is ~31 bits,
	// so a retry collides roughly never, and the loop below would catch it anyway.
	usernameSuffixLen = 6
	// usernameAlphabet is the suffix alphabet: lower-case base-36, so a suffix
	// can never reintroduce a character the shape forbids.
	usernameAlphabet = "abcdefghijklmnopqrstuvwxyz0123456789"
)

// ErrInvalidUsername is a caller-supplied handle that does not fit the shape.
var ErrInvalidUsername = fmt.Errorf("a username must be 3-39 characters of lower-case letters, digits and dashes, not starting or ending with a dash")

// NormalizeUsername renders a caller's or a name's text into a handle candidate.
//
// It collapses every run of non-alphanumeric characters to a single dash, trims
// leading and trailing dashes, lower-cases, and truncates the base to
// usernameBaseMax. It returns "" when nothing alphanumeric survives, which is the
// caller's signal to fall back to the generated form — an agent named "!!!" gets
// a generated handle rather than an invalid one.
//
// It does NOT validate length or the leading/trailing rule; AppendSuffix and
// the generated path produce values that satisfy both, and a caller who supplies
// a bare handle is validated separately. This is a projection, and the guarantee
// it gives is only "no character outside the allowed set appears".
func NormalizeUsername(raw string) string {
	var b strings.Builder
	prevDash := false
	for _, r := range strings.ToLower(strings.TrimSpace(raw)) {
		isAlnum := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
		if isAlnum {
			b.WriteRune(r)
			prevDash = false
			continue
		}
		if b.Len() > 0 && !prevDash {
			b.WriteByte('-')
			prevDash = true
		}
	}
	slug := strings.Trim(b.String(), "-")
	if len(slug) > usernameBaseMax {
		slug = strings.Trim(slug[:usernameBaseMax], "-")
	}
	return slug
}

// ValidUsername reports whether a caller-supplied handle fits the shape the
// column's CHECK enforces. Exact and case-sensitive: `Alex` is not `alex`, and a
// handle that is not already lower-cased is refused rather than silently fixed,
// because a caller who typed `Alex` meant `Alex` and a handle that changed on the
// way to storage is the kind of surprise that becomes a bug report.
func ValidUsername(given string) bool {
	if len(given) < usernameMin || len(given) > usernameMax {
		return false
	}
	if given != strings.ToLower(given) {
		return false
	}
	for i, r := range given {
		isAlnum := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
		if isAlnum {
			continue
		}
		// A dash is allowed only between two alphanumerics.
		if r == '-' && i > 0 && i < len(given)-1 {
			continue
		}
		return false
	}
	return true
}

// GenerateUsernameBase builds the deterministic half of a generated handle: the
// normalised display name, or "agent" when nothing survives.
func GenerateUsernameBase(name string) string {
	if base := NormalizeUsername(name); base != "" {
		return base
	}
	return "agent"
}

// randomSuffix returns usernameSuffixLen base-36 characters from crypto/rand,
// or — if randomness is unavailable — a time-derived fallback.
//
// THE FALLBACK IS NOT WEAK IN A WAY THAT MATTERS: the suffix's job is to avoid
// a COLLISION, not to be unguessable, and the unique index plus the retry loop
// catch a collision whatever the suffix. A crypto/rand failure is reported by
// NewToken before registration gets anywhere near success, so reaching this
// fallback means the process could not mint entropy and is already failing.
func randomSuffix() string {
	buf := make([]byte, usernameSuffixLen)
	if _, err := rand.Read(buf); err != nil {
		return strings.Repeat("0", usernameSuffixLen)
	}
	out := make([]byte, usernameSuffixLen)
	for i, b := range buf {
		n := int64(b) % int64(len(usernameAlphabet))
		out[i] = usernameAlphabet[n]
	}
	return string(out)
}

// appendSuffix joins a base and a random suffix with a dash, keeping the whole
// within usernameMax even if the base is at its ceiling.
func appendSuffix(base string) string {
	room := usernameMax - len(base) - 1
	if room < usernameSuffixLen {
		base = strings.Trim(base[:usernameMax-usernameSuffixLen-1], "-")
	}
	return base + "-" + randomSuffix()
}
